sources={'javax/microedition/midlet/MIDlet.java': 'package javax.microedition.midlet; public abstract class MIDlet { protected MIDlet() {} public final void notifyDestroyed() {} }', 'javax/microedition/lcdui/Command.java': 'package javax.microedition.lcdui; public class Command { public final String label; public final int type,priority; public Command(String s,int t,int p) {label=s;type=t;priority=p;} }', 'javax/microedition/lcdui/CommandListener.java': 'package javax.microedition.lcdui; public interface CommandListener { void commandAction(Command c,Displayable d); }', 'javax/microedition/lcdui/Displayable.java': 'package javax.microedition.lcdui; public class Displayable { public final java.util.List<Command> commands=new java.util.ArrayList<Command>(); public int getWidth(){return Canvas.width;} public int getHeight(){return Canvas.height;} public void addCommand(Command c) {if(!commands.contains(c))commands.add(c);} public void removeCommand(Command c){commands.remove(c);} public void setCommandListener(CommandListener l) {} }', 'javax/microedition/lcdui/Display.java': 'package javax.microedition.lcdui; public class Display { private static final java.util.List<Runnable> queue=new java.util.ArrayList<Runnable>(); public static Display getDisplay(javax.microedition.midlet.MIDlet m){return new Display();} public void setCurrent(Displayable d){} public void callSerially(Runnable r){synchronized(queue){queue.add(r);}} public static void flush(){while(true){Runnable r; synchronized(queue){if(queue.isEmpty())return;r=queue.remove(0);}r.run();}} public static int pending(){synchronized(queue){return queue.size();}} }', 'javax/microedition/lcdui/Canvas.java': 'package javax.microedition.lcdui; public abstract class Canvas extends Displayable { public static int width=176,height=200; public int getWidth(){return width;} public int getHeight(){return height;} public void repaint(){} public int getGameAction(int k){return k==53?8:0;} protected abstract void paint(Graphics g); }', 'javax/microedition/lcdui/Item.java': 'package javax.microedition.lcdui; public class Item {}', 'javax/microedition/lcdui/Choice.java': 'package javax.microedition.lcdui; public interface Choice {}', 'javax/microedition/lcdui/Image.java': 'package javax.microedition.lcdui; public class Image {}', 'javax/microedition/lcdui/ChoiceGroup.java': 'package javax.microedition.lcdui; public class ChoiceGroup extends Item implements Choice { public ChoiceGroup(String s,int t,String[] a,Image[] i){} public void setSelectedIndex(int n,boolean b){} public int getSelectedIndex(){return 1;} }', 'javax/microedition/lcdui/Form.java': 'package javax.microedition.lcdui; public class Form extends Displayable { public java.util.ArrayList<String> text=new java.util.ArrayList<String>(); public Form(String s){} public int append(String s){text.add(s);return text.size()-1;} public int append(Item i){return 0;} }', 'javax/microedition/lcdui/Font.java': 'package javax.microedition.lcdui; public class Font { final java.awt.Font font; private final java.awt.FontMetrics fm; private Font(int style,int size){font=new java.awt.Font("Dialog",style==1?java.awt.Font.BOLD:java.awt.Font.PLAIN,size==16?22:12); fm=new java.awt.image.BufferedImage(1,1,2).createGraphics().getFontMetrics(font);} public static Font getFont(int face,int style,int size){return new Font(style,size);} public int getHeight(){return fm.getHeight();} public int stringWidth(String s){return fm.stringWidth(s);} }', 'javax/microedition/lcdui/Graphics.java': 'package javax.microedition.lcdui;\npublic class Graphics {\n public final java.awt.Graphics2D g; public int clippedText=0; private final int width,height;\n public Graphics(java.awt.Graphics2D g,int w,int h){this.g=g;width=w;height=h;g.setRenderingHint(java.awt.RenderingHints.KEY_ANTIALIASING,java.awt.RenderingHints.VALUE_ANTIALIAS_ON);}\n public void setColor(int rgb){g.setColor(new java.awt.Color(rgb));}\n public void fillRect(int x,int y,int w,int h){g.fillRect(x,y,w,h);}\n public void drawLine(int x,int y,int a,int b){g.drawLine(x,y,a,b);}\n public void drawArc(int x,int y,int w,int h,int a,int b){g.drawArc(x,y,w,h,a,b);}\n public void fillArc(int x,int y,int w,int h,int a,int b){g.fillArc(x,y,w,h,a,b);}\n public void setFont(Font f){g.setFont(f.font);}\n public void drawString(String s,int x,int y,int anchor){java.awt.FontMetrics f=g.getFontMetrics();int w=f.stringWidth(s);if((anchor&1)!=0)x-=w/2;else if((anchor&8)!=0)x-=w; if(x<0||x+w>width||y<0||y+f.getHeight()>height){clippedText++;System.out.println("CLIP: "+s+" at "+x+","+y+" "+width+"x"+height);}g.drawString(s,x,y+f.getAscent());}\n}'}
